const toRename: Record<string, string> = {};
// Helpers can define internal functions whose names clash with other
// bindings of the helper itself (e.g. the `set` helper defines a local
// `set` function referenced by the exported `_set` function). When
// renaming to avoid conflicts with the bindings of the program, we must
// also avoid clashing with the helper's own bindings, otherwise the
// generated code would be broken (e.g. a recursive `_set` call).
const reservedNames = new Set(localBindings || []);
